import numpy as np, itertools
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
one=np.ones_like(t)
base=[one,np.sqrt(t),t**1.5/x]
F={'v':v,'v2':v*v,'v3':v**3,'sqrtv':np.sqrt(v),'1/v':1/v,'logv':np.log(v),'x':x,'1/x':1/x,'x2':x*x,'t':t,'sqrtt':np.sqrt(t),'t1.5':t**1.5,'t/x':t/x,'sqrtt/x':np.sqrt(t)/x,'t2':t*t,'1/t':1/t}
L={}
for k in F: L[k]=F[k]
for k1,k2 in itertools.combinations(F,2):
    L[k1+'*'+k2]=F[k1]*F[k2]
    L[k1+'/'+k2]=F[k1]/F[k2]
    L[k2+'/'+k1]=F[k2]/F[k1]
res=[]
for nm,f in L.items():
    Y=np.column_stack(base+[f]); cc=np.linalg.lstsq(Y,a,rcond=None)[0]
    rr=a-Y@cc; res.append((np.mean(rr**2)/np.var(a),nm,np.round(cc,4)))
for e,nm,cc in sorted(res,key=lambda z:z[0])[:8]: print('%.3e'%e,nm,cc)
